package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for MathUtils.factorialLog
 */
public class MathUtils_factorialLog_TriageGen1Test {

    private static final double DELTA = 1e-15;





    @Test
    public void testFactorialLog_Positive() {
        // n = 2: log(2)
        assertEquals(Math.log(2.0), MathUtils.factorialLog(2), DELTA);

        // n = 3: log(2) + log(3) = log(6)
        assertEquals(Math.log(6.0), MathUtils.factorialLog(3), DELTA);

        // n = 5: log(120)
        assertEquals(Math.log(120.0), MathUtils.factorialLog(5), DELTA);
    }




}

